package camigrations

// sql001ReferralCode adds subscribers.referral_code: a short, unique,
// case-insensitive (stored uppercase) code that subscribers share to refer
// others. Codes are generated by a column DEFAULT so that no insert query
// (API, import, bulk) needs to know about them.
const sql001ReferralCode = `
-- 6 chars from Crockford base32 minus I, L, O, U (no ambiguous characters).
-- Loops until the code is unused. Not a secret, only a share handle.
CREATE OR REPLACE FUNCTION ca_gen_referral_code() RETURNS TEXT AS $$
DECLARE
    alphabet CONSTANT TEXT := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
    code TEXT;
BEGIN
    LOOP
        code := '';
        FOR i IN 1..6 LOOP
            code := code || SUBSTR(alphabet, 1 + FLOOR(RANDOM() * 32)::INT, 1);
        END LOOP;

        EXIT WHEN NOT EXISTS (SELECT 1 FROM subscribers WHERE referral_code = code);
    END LOOP;
    RETURN code;
END;
$$ LANGUAGE plpgsql VOLATILE;

ALTER TABLE subscribers ADD COLUMN IF NOT EXISTS referral_code TEXT;
UPDATE subscribers SET referral_code = ca_gen_referral_code() WHERE referral_code IS NULL;
ALTER TABLE subscribers ALTER COLUMN referral_code SET DEFAULT ca_gen_referral_code();
ALTER TABLE subscribers ALTER COLUMN referral_code SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_subs_referral_code ON subscribers(referral_code);
`
